public class ImageDataCarrier implements DataCarrier {
    private byte[] imageData;
    private String format;

    public ImageDataCarrier(String filePath) throws IOException {
        // Read image file
        this.imageData = Files.readAllBytes(Paths.get(filePath));
        this.format = getFormatFromBytes(imageData);
    }

    // Helper method to determine image format from bytes
    private String getFormatFromBytes(byte[] bytes) {
        // Simple format detection based on magic numbers
        if (bytes.length >= 2 && bytes[0] == (byte) 0xFF && bytes[1] == (byte) 0xD8) {
            return "JPEG";
        } else if (bytes.length >= 4 && bytes[0] == (byte) 0x89 && bytes[1] == (byte) 0x50 && bytes[2] == (byte) 0x4E && bytes[3] == (byte) 0x47) {
            return "PNG";
        } else {
            return "Unknown";
        }
    }

    @Override
    public byte[] getBytes() {
        return imageData;
    }

    @Override
    public void setBytes(byte[] bytes) {
        this.imageData = bytes;
    }

    @Override
    public int getSize() {
        return imageData.length;
    }

    @Override
    public String getFormat() {
        return format;
    }

    @Override
    public void save(String filePath) throws IOException {
        Files.write(Paths.get(filePath), imageData);
    }
}
