```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <stdexcept>

// Function to merge two sorted arrays in-place with a single pointer
void mergeSortedArrays(std::vector<int>& arr1, std::vector<int>& arr2) {
    // Check if the arrays are valid
    if (arr1.empty() || arr2.empty()) {
        throw std::invalid_argument("Arrays cannot be empty.");
    }

    // Get the sizes of the arrays
    int n = arr1.size();
    int m = arr2.size();

    // Check if the arrays are sorted
    for (int i = 1; i < n; ++i) {
        if (arr1[i] < arr1[i - 1]) {
            throw std::invalid_argument("First array is not sorted.");
        }
    }
    for (int i = 1; i < m; ++i) {
        if (arr2[i] < arr2[i - 1]) {
            throw std::invalid_argument("Second array is not sorted.");
        }
    }

    // Ensure that arr1 is the larger array to avoid overflow
    if (n < m) {
        std::swap(arr1, arr2);
        std::swap(n, m);
    }

    // Merge the two arrays in-place
    int i = 0; // Pointer for arr1
    int j = 0; // Pointer for arr2
    int k = 0; // Pointer for the merged array

    // Merge the two arrays using a single pointer
    while (i < n && j < m) {
        if (arr1[i] <= arr2[j]) {
            arr1[k++] = arr1[i++];
        } else {
            arr1[k++] = arr2[j++];
        }
    }

    // Copy the remaining elements from arr2 to arr1
    while (j < m) {
        arr1[k++] = arr2[j++];
    }

    // Now, arr1 contains the merged array, and arr2 is empty
    arr2.clear();
}

int main() {
