        std::cout << "Merged array: ";
        for (int num : arr1) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
